    input[type="color"]::-webkit-color-swatch { border: 1px solid #0002; border-radius: 5px; }
    input[type="color"]::-moz-color-swatch { border: 1px solid #0002; border-radius: 5px; }
    .hex-input {
      width: 100%;
      min-width: 0;
      min-height: 27px;
      border: 0;
      border-radius: 3px;
      padding: 0 3px;
      background: none;
      color: #39334f;
      font: 12px var(--mono);
