    .opacity-field { margin-top: 15px; }
    .results { display: grid; gap: 16px; min-width: 0; }
    .preview { overflow: hidden; }
    .preview-header { padding: 13px 17px; min-height: 49px; }
    .live { display: inline-flex; align-items: center; gap: 6px; color: #5944af; background: #f0ebff; border-radius: 20px; padding: 4px 9px; font-size: 11px; font-weight: 700; }
