    .plan-label { font-size: 13px; font-weight: 700; color: #5940c5; }
    .price { display: flex; align-items: baseline; gap: 5px; margin-top: 6px; }
    .price strong { font-size: 45px; font-weight: 700; line-height: 1; letter-spacing: -.075em; }
    .billing { font-size: 13px; color: var(--muted); }
    .plan-description { margin-top: 9px; color: var(--muted); font-size: 12px; }
    .features { list-style: none; padding: 14px 0 0; margin: 15px 0 17px; border-top: 1px solid #efecf5; display: grid; gap: 8px; }
    .features li { display: flex; align-items: center; gap: 8px; font-size: 12px; }
    .features ryugi-icon { color: #6549d5; }
    .sample-cta { display: block; width: 100%; border-radius: 8px; background: #6348d9; color: #fff; text-align: center; padding: 9px 10px; font-weight: 700; font-size: 12px; line-height: 18px; }
    .code-panel { padding: 13px 16px 15px; min-width: 0; }
    .code-actions { display: flex; align-items: center; gap: 8px; }
    .copy-status { font-size: 12px; color: var(--muted); }
    .copy { padding: 0 10px; border: 1px solid #e5dffe; background: #f4f0ff; color: #5136b9; }
    .copy:hover { background: #ece4ff; }
