    @media (max-width: 770px) {
      main { padding: 28px 18px 30px; }
      .topbar-inner { padding: 13px 18px; }
      .workspace { grid-template-columns: minmax(0, 1fr); gap: 16px; }
      .settings { padding: 16px; }
      .sliders { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; margin-top: 14px; }
      .stage { min-height: 350px; }
    }
    @media (max-width: 375px) {
      .sliders { grid-template-columns: minmax(0, 1fr); }
      .copy-status:empty { display: none; }
    }
  </style>
</head>
<body>
  <header class="topbar">
    <div class="topbar-inner"><span class="mark" aria-hidden="true"><ryugi-icon name="layers" size="18"></ryugi-icon></span>Shadow Studio</div>
  </header>
  <main>
    <div class="intro">
      <h1>Pricing card shadow</h1>
      <p>Fine-tune the shadow on a sample card and copy the CSS when it looks right.</p>
    </div>
    <div class="workspace">
      <section class="panel settings" aria-labelledby="settings-title">
        <div class="panel-heading">
          <h2 id="settings-title">Shadow settings</h2>
          <button class="reset" id="reset-shadow" type="button"><ryugi-icon name="rotate-ccw" size="14" aria-hidden="true"></ryugi-icon> Reset</button>
        </div>
        <div class="sliders">
          <div>
            <div class="field-heading"><label for="elevation">Elevation</label><output id="elevation-value" for="elevation">16 px</output></div>
            <input id="elevation" type="range" min="-48" max="64" value="16" aria-describedby="elevation-help">
            <div id="elevation-help" class="field-help">Vertical offset</div>
          </div>
          <div>
            <div class="field-heading"><label for="blur">Blur</label><output id="blur-value" for="blur">36 px</output></div>
            <input id="blur" type="range" min="0" max="120" value="36">
          </div>
          <div>
            <div class="field-heading"><label for="spread">Spread</label><output id="spread-value" for="spread">−6 px</output></div>
            <input id="spread" type="range" min="-32" max="40" value="-6">
          </div>
          <div>
            <div class="field-heading"><label for="corner-radius">Corner radius</label><output id="corner-radius-value" for="corner-radius">20 px</output></div>
            <input id="corner-radius" type="range" min="0" max="64" value="20">
          </div>
        </div>
        <div class="color-section">
          <label for="shadow-color">Shadow colour</label>
          <div class="color-control">
            <input id="shadow-color" type="color" value="#38265f">
            <input id="shadow-hex" class="hex-input" type="text" aria-label="Shadow colour hex code" value="#38265F" maxlength="7" spellcheck="false" autocomplete="off">
          </div>
          <div class="opacity-field">
            <div class="field-heading"><label for="shadow-opacity">Opacity</label><output id="shadow-opacity-value" for="shadow-opacity">22%</output></div>
            <input id="shadow-opacity" type="range" min="0" max="100" value="22">
          </div>
        </div>
      </section>
      <div class="results">
        <section class="panel preview" aria-labelledby="preview-title">
          <div class="panel-heading preview-header">
            <h2 id="preview-title">Card preview</h2>
            <span class="live">Live</span>
          </div>
          <div class="stage">
            <article class="pricing-card" id="pricing-card" aria-label="Pro pricing card example">
              <h3 class="plan-label" style="margin:0">Pro plan</h3>
              <p class="price"><strong>$29</strong><span class="billing">/ month</span></p>
              <p class="plan-description">For teams ready to do more.</p>
              <ul class="features">
                <li><ryugi-icon name="check" size="14" aria-hidden="true"></ryugi-icon> Unlimited projects</li>
                <li><ryugi-icon name="check" size="14" aria-hidden="true"></ryugi-icon> Team collaboration</li>
                <li><ryugi-icon name="check" size="14" aria-hidden="true"></ryugi-icon> Priority support</li>
              </ul>
              <span class="sample-cta">Get started</span>
            </article>
          </div>
        </section>
        <section class="panel code-panel" aria-labelledby="css-title">
          <div class="panel-heading">
            <h2 id="css-title">Generated CSS</h2>
            <div class="code-actions">
              <span class="copy-status" id="copy-status" role="status"></span>
              <button class="copy" id="copy-css" type="button"><ryugi-icon name="copy" size="14" aria-hidden="true"></ryugi-icon> Copy CSS</button>
            </div>
          </div>
          <pre><code id="css-code"><span class="code-selector">.pricing-card</span> {
  <span class="code-property">border-radius</span>: <span id="css-radius" class="code-value"></span>;
  <span class="code-property">box-shadow</span>: <span id="css-shadow" class="code-value"></span>;
}</code></pre>
        </section>
      </div>
    </div>
  </main>
  <script>
    const byId = (id) => document.getElementById(id);
    const sliders = ['"'elevation', 'blur', 'spread', 'corner-radius', 'shadow-opacity'].map(byId);
    const colorPicker = byId('shadow-color');
    const hexInput = byId('shadow-hex');
    const card = byId('pricing-card');
    const code = byId('css-code');
    const copyButton = byId('copy-css');
    const copyStatus = byId('copy-status');

    function render() {
      for (const slider of sliders) {
        const isOpacity = slider.id === 'shadow-opacity';
        const value = slider.valueAsNumber;
        const unit = isOpacity ? '%' : ' px';
        byId(slider.id + '-value').textContent = String(value).replace('-', '−') + unit;
        slider.setAttribute('aria-valuetext', value + (isOpacity ? ' percent' : ' pixels'));
        const position = (value - Number(slider.min)) / (Number(slider.max) - Number(slider.min));
        slider.style.setProperty('--fill', position * 100 + '%');
      }

      const [elevation, blur, spread, radius, opacity] = sliders.map((slider) => slider.valueAsNumber);
      const hex = colorPicker.value.slice(1);
      const [red, green, blue] = hex.match(/../g).map((channel) => parseInt(channel, 16));
      const radiusCss = radius + 'px';
      const shadowCss = "'`0 ${elevation}px ${blur}px ${spread}px rgb(${red} ${green} ${blue} / ${opacity}%)`;
      card.style.borderRadius = radiusCss;
      card.style.boxShadow = shadowCss;
      byId('"'css-radius').textContent = radiusCss;
      byId('css-shadow').textContent = shadowCss;
      copyStatus.textContent = '';
    }

    function syncPicker() {
      hexInput.value = colorPicker.value.toUpperCase();
      hexInput.removeAttribute('aria-invalid');
      render();
    }

    function readHex() {
      const value = hexInput.value.trim().replace(/"'^#/, '"'');
      if ("'!/''^(?:[a-f'"\\d]{3}|[a-f\\d]{6})"'$/i.test(value)) {
        hexInput.setAttribute('"'aria-invalid', 'true');
        return false;
      }

      const expanded = value.length === 3 ? Array.from(value, (digit) => digit + digit).join('') : value;
      colorPicker.value = '#' + expanded;
      hexInput.removeAttribute('aria-invalid');
      render();
      return true;
    }

    for (const eventName of ['input', 'change']) {
      sliders.forEach((slider) => slider.addEventListener(eventName, render));
      colorPicker.addEventListener(eventName, syncPicker);
    }
    hexInput.addEventListener('input', readHex);
    hexInput.addEventListener('change', () => {
      if (readHex()) hexInput.value = colorPicker.value.toUpperCase();
    });
    byId('reset-shadow').addEventListener('click', () => {
      sliders.forEach((slider) => { slider.value = slider.defaultValue; });
      colorPicker.value = colorPicker.defaultValue;
      syncPicker();
    });

    function selectCode() {
      const selection = window.getSelection();
      const range = document.createRange();
      range.selectNodeContents(code);
      selection.removeAllRanges();
      selection.addRange(range);
      return selection;
    }

    copyButton.addEventListener('click', async () => {
      const css = code.textContent;
      let copied = false;
      try {
        await navigator.clipboard.writeText(css);
        copied = true;
      } catch {
        const selection = selectCode();
        if (code.textContent === css) {
          try {
            copied = document.execCommand('copy');
          } catch {
            copied = false;
          }
        }
        if (copied) selection.removeAllRanges();
      }
      copyStatus.textContent = copied && code.textContent === css
        ? 'Copied"'!'"'
        : copied ? '' : 'CSS selected. Press Ctrl+C or ⌘C.';
    });

    render();
  </script>
</body>
</html>
